-- 250 популярных книг. rating — место в рейтинге (1 = самая популярная),
-- rating_ball вычисляется из места: от 9.79 (1-е место) до 8.05 (250-е место).
INSERT INTO books (rating, name, author, year, rating_ball, description)
SELECT v.rating,
       v.name,
       v.author,
       v.year,
       ROUND((9.8 - v.rating * 0.007)::numeric, 2),
       v.description
FROM (VALUES
    (1, 'Война и мир', 'Лев Толстой', 1869, 'Эпопея о русском обществе в эпоху наполеоновских войн, судьбах семей Ростовых, Болконских и Безуховых, о войне, любви и поиске смысла жизни.'),
    (2, 'Преступление и наказание', 'Фёдор Достоевский', 1866, 'Бедный студент Родион Раскольников совершает убийство старухи-процентщицы, чтобы проверить свою теорию, и переживает мучительное нравственное наказание.'),
    (3, 'Мастер и Маргарита', 'Михаил Булгаков', 1967, 'Воланд со свитой приезжает в Москву 1930-х годов, а параллельно разворачивается история Мастера, его романа о Понтии Пилате и преданной любви Маргариты.'),
    (4, '1984', 'Джордж Оруэлл', 1949, 'Антиутопия о тоталитарном государстве, где Большой Брат следит за каждым, а Уинстон Смит решается на запретную любовь и сомнение.'),
    (5, 'Анна Каренина', 'Лев Толстой', 1877, 'Трагическая история любви замужней Анны к офицеру Вронскому на фоне поисков смысла жизни помещиком Константином Лёвиным.'),
    (6, 'Братья Карамазовы', 'Фёдор Достоевский', 1880, 'Философский роман об отцеубийстве, вере и свободе, о трёх братьях — Дмитрии, Иване и Алёше — и их отце Фёдоре Павловиче.'),
    (7, 'Евгений Онегин', 'Александр Пушкин', 1833, 'Роман в стихах о скучающем столичном денди Онегине, отвергнувшем любовь Татьяны Лариной и убившем на дуэли друга Ленского.'),
    (8, 'Мёртвые души', 'Николай Гоголь', 1842, 'Авантюрист Павел Чичиков объезжает помещиков, скупая умерших крестьян, числящихся живыми, — сатирическая панорама русской провинции.'),
    (9, 'Идиот', 'Фёдор Достоевский', 1869, 'Добрый и наивный князь Мышкин возвращается в Россию и оказывается в водовороте страстей вокруг Настасьи Филипповны и Аглаи Епанчиной.'),
    (10, 'Сто лет одиночества', 'Габриэль Гарсиа Маркес', 1967, 'Сага о семи поколениях рода Буэндиа в вымышленном городке Макондо — вершина магического реализма.'),
    (11, 'Маленький принц', 'Антуан де Сент-Экзюпери', 1943, 'Философская сказка о мальчике с далёкой планеты, его розе и встрече с лётчиком, потерпевшим аварию в пустыне.'),
    (12, 'Гордость и предубеждение', 'Джейн Остин', 1813, 'История Элизабет Беннет и гордого мистера Дарси, которым предстоит преодолеть собственные предрассудки на пути к любви.'),
    (13, 'Убить пересмешника', 'Харпер Ли', 1960, 'Глазами девочки Глазастика показан суд над темнокожим мужчиной в американском Юге и борьба её отца-адвоката за справедливость.'),
    (14, 'Великий Гэтсби', 'Фрэнсис Скотт Фицджеральд', 1925, 'Таинственный миллионер Джей Гэтсби устраивает роскошные вечеринки, чтобы вернуть давнюю любовь Дэйзи, — портрет эпохи джаза.'),
    (15, 'Над пропастью во ржи', 'Джером Д. Сэлинджер', 1951, 'Подросток Холден Колфилд, исключённый из школы, бродит по Нью-Йорку и пытается понять фальшивый мир взрослых.'),
    (16, 'Три товарища', 'Эрих Мария Ремарк', 1936, 'Трое друзей, прошедших Первую мировую, держат автомастерскую в Германии, а один из них переживает трагическую любовь к Патриции.'),
    (17, 'Отцы и дети', 'Иван Тургенев', 1862, 'Конфликт поколений: нигилист Евгений Базаров спорит с дворянами Кирсановыми и сталкивается с силой любви.'),
    (18, 'Герой нашего времени', 'Михаил Лермонтов', 1840, 'Роман из нескольких повестей о Григории Печорине — умном, разочарованном и разрушающем чужие судьбы офицере на Кавказе.'),
    (19, 'Горе от ума', 'Александр Грибоедов', 1825, 'Комедия в стихах: Чацкий возвращается в Москву и вступает в конфликт с фамусовским обществом, не принимающим его свободомыслия.'),
    (20, 'Тихий Дон', 'Михаил Шолохов', 1928, 'Эпопея о донском казачестве в годы Первой мировой и Гражданской войны и о мятущемся Григории Мелехове.'),
    (21, 'Двенадцать стульев', 'Илья Ильф, Евгений Петров', 1928, 'Остап Бендер и Киса Воробьянинов охотятся за бриллиантами, спрятанными в одном из двенадцати гарнитурных стульев.'),
    (22, 'Золотой телёнок', 'Илья Ильф, Евгений Петров', 1931, 'Великий комбинатор Остап Бендер пытается отобрать миллион у подпольного советского миллионера Корейко.'),
    (23, 'Собачье сердце', 'Михаил Булгаков', 1925, 'Профессор Преображенский пересаживает бездомному псу Шарику человеческие органы, и тот превращается в хама Шарикова.'),
    (24, 'Белая гвардия', 'Михаил Булгаков', 1925, 'Семья Турбиных в Киеве 1918 года пытается сохранить дом и честь в хаосе Гражданской войны.'),
    (25, 'Доктор Живаго', 'Борис Пастернак', 1957, 'Жизнь врача и поэта Юрия Живаго, его любовь к Ларе на фоне революции и Гражданской войны.'),
    (26, 'Обломов', 'Иван Гончаров', 1859, 'Добрый и мечтательный барин Илья Обломов проводит жизнь на диване, не в силах противостоять собственной апатии.'),
    (27, 'Капитанская дочка', 'Александр Пушкин', 1836, 'Молодой офицер Пётр Гринёв попадает в гущу Пугачёвского восстания и сохраняет честь и любовь к Маше Мироновой.'),
    (28, 'Ревизор', 'Николай Гоголь', 1836, 'Чиновники уездного города принимают мелкого проходимца Хлестакова за ревизора из Петербурга — бессмертная комедия.'),
    (29, 'Вишнёвый сад', 'Антон Чехов', 1904, 'Пьеса о разорившейся помещице Раневской, чьё родовое имение с вишнёвым садом уходит с молотка.'),
    (30, 'Гроза', 'Александр Островский', 1859, 'Драма о Катерине, задыхающейся в «тёмном царстве» купеческого города Калинова.'),
    (31, 'Бесы', 'Фёдор Достоевский', 1872, 'Роман-предупреждение о революционном кружке, его лидере Петре Верховенском и загадочном Николае Ставрогине.'),
    (32, 'Отверженные', 'Виктор Гюго', 1862, 'Бывший каторжник Жан Вальжан стремится к добру, а его преследует непреклонный инспектор Жавер.'),
    (33, 'Собор Парижской Богоматери', 'Виктор Гюго', 1831, 'Средневековый Париж, цыганка Эсмеральда, горбун-звонарь Квазимодо и одержимый страстью архидьякон Фролло.'),
    (34, 'Граф Монте-Кристо', 'Александр Дюма', 1844, 'Моряк Эдмон Дантес, невинно заключённый в замок Иф, бежит, находит сокровище и мстит своим врагам.'),
    (35, 'Три мушкетёра', 'Александр Дюма', 1844, 'Юный гасконец и три мушкетёра — Атос, Портос и Арамис — противостоят интригам кардинала Ришельё и миледи.'),
    (36, 'Дон Кихот', 'Мигель де Сервантес', 1605, 'Обедневший идальго, начитавшись рыцарских романов, отправляется на подвиги вместе с оруженосцем Санчо Пансой.'),
    (37, 'Гамлет', 'Уильям Шекспир', 1603, 'Датский принц мстит за отца, убитого дядей, и мучается вопросом «быть или не быть».'),
    (38, 'Ромео и Джульетта', 'Уильям Шекспир', 1597, 'Трагедия о любви юных наследников двух враждующих семейств Вероны.'),
    (39, 'Божественная комедия', 'Данте Алигьери', 1320, 'Поэма о странствии Данте по Аду, Чистилищу и Раю в сопровождении Вергилия и Беатриче.'),
    (40, 'Фауст', 'Иоганн Вольфганг Гёте', 1808, 'Учёный доктор Фауст заключает договор с Мефистофелем в поисках мгновения, которое захочется остановить.'),
    (41, 'Джейн Эйр', 'Шарлотта Бронте', 1847, 'Сирота Джейн становится гувернанткой в поместье Торнфилд и влюбляется в его мрачного хозяина мистера Рочестера.'),
    (42, 'Грозовой перевал', 'Эмили Бронте', 1847, 'Разрушительная страсть Хитклифа и Кэтрин Эрншо на фоне суровых йоркширских пустошей.'),
    (43, 'Портрет Дориана Грея', 'Оскар Уайльд', 1890, 'Юный красавец сохраняет молодость, а все его пороки отражаются на написанном с него портрете.'),
    (44, 'Приключения Тома Сойера', 'Марк Твен', 1876, 'Озорной мальчишка из городка на Миссисипи ищет клад, становится свидетелем убийства и влюбляется.'),
    (45, 'Приключения Гекльберри Финна', 'Марк Твен', 1884, 'Гек сбегает от отца и сплавляется на плоту по Миссисипи вместе с беглым рабом Джимом.'),
    (46, 'Моби Дик', 'Герман Мелвилл', 1851, 'Капитан Ахав одержимо преследует белого кита, лишившего его ноги.'),
    (47, 'Старик и море', 'Эрнест Хемингуэй', 1952, 'Старый кубинский рыбак Сантьяго в одиночку сражается в открытом море с гигантской рыбой.'),
    (48, 'Прощай, оружие!', 'Эрнест Хемингуэй', 1929, 'Американский лейтенант на итальянском фронте Первой мировой и его любовь к английской медсестре.'),
    (49, 'По ком звонит колокол', 'Эрнест Хемингуэй', 1940, 'Американский подрывник Роберт Джордан готовится взорвать мост в тылу франкистов во время гражданской войны в Испании.'),
    (50, 'Унесённые ветром', 'Маргарет Митчелл', 1936, 'Своенравная Скарлетт О’Хара борется за выживание и любовь во время Гражданской войны в США.'),
    (51, 'О дивный новый мир', 'Олдос Хаксли', 1932, 'Антиутопия о мире всеобщего потребления и счастья, где людей выращивают в пробирках.'),
